func double(value u32) u32 => value * u32(2)
func apply(value u32, callback func(u32) u32) u32 => callback(value)
emit apply(u32(21), double) # 42u32

func announce(value) { emit value; return value + 1 }
let result = announce(4)
emit result
# 4u64
# 5u64

let safe = redact(withdebug(error(InvalidArgument, "bad input"), "token", "secret"))
emit safe.debug
# []

enum Status { Ready, Done }
emit Status.Ready
# Status.Ready

let value = 7
emit match value { number n when n > 0 => n, _ => 0 }
# 7u64
